long long fib_recursive(int n) {
    return n < 2 ? n : fib_recursive(n - 1) + fib_recursive(n - 2);
}

long long fib_iterative(int n) {
    long long a = 0, b = 1;
    for (int i = 0; i < n; ++i) {
        long long next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int demo() {
    return static_cast<int>(fib_recursive(15) + fib_iterative(50) % 1000);
}

#include <vector>

using Mat = std::vector<std::vector<double>>;

Mat multiply_ikj(const Mat& a, const Mat& b) {
    std::size_t n = a.size(), m = b[0].size(), k = b.size();
    Mat c(n, std::vector<double>(m, 0.0));
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t p = 0; p < k; ++p) {
            double aip = a[i][p];
            for (std::size_t j = 0; j < m; ++j) {
                c[i][j] += aip * b[p][j];
            }
        }
    }
    return c;
}

int demo() {
    Mat a{{1, 2}, {3, 4}}, b{{5, 6}, {7, 8}};
    auto c = multiply_ikj(a, b);
    return static_cast<int>(c[0][0] + c[1][1]);
}

